import{_ as i,o as n,c as u,a2 as t}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Mfumo wa Tathmini ya Kiwango cha Usawa","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0029-共生度评估体系.md","filePath":"sw/0029-共生度评估体系.md"}'),o={name:"sw/0029-共生度评估体系.md"};function w(h,a,k,m,e,s){return n(),u("div",null,[...a[0]||(a[0]=[t('<h1 id="mfumo-wa-tathmini-ya-kiwango-cha-usawa" tabindex="-1">Mfumo wa Tathmini ya Kiwango cha Usawa <a class="header-anchor" href="#mfumo-wa-tathmini-ya-kiwango-cha-usawa" aria-label="Permalink to &quot;Mfumo wa Tathmini ya Kiwango cha Usawa&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>29</td></tr><tr><td>Moduli</td><td>Mfumo wa Neo na Kanuni za Usawa</td></tr><tr><td>Maneno Muhimu</td><td>Kiwango cha usawa, Vielelezo vya tathmini, Mfumo wa kiasi, Uainishaji wa viwango, Kuboresha kwa kila mara</td></tr></tbody></table><h2 id="_1-dhana-na-umuhimu-wa-kiwango-cha-usawa" tabindex="-1">1. Dhana na Umuhimu wa Kiwango cha Usawa <a class="header-anchor" href="#_1-dhana-na-umuhimu-wa-kiwango-cha-usawa" aria-label="Permalink to &quot;1. Dhana na Umuhimu wa Kiwango cha Usawa&quot;">​</a></h2><p>Kiwango cha usawa ni kiashiria cha kiasi cha jumla kinachopima &quot;kiwango cha usawa&quot; cha eneo, shirika, au mtu binafsi katika utamaduni wa usawa wa neo. Kinachojulikana kama &quot;kiwango cha usawa&quot; kinahusu kiwango ambacho kipengele cha tathmini kimefanya mazoezi ya falsafa ya usawa, kimeungana katika mtandao wa usawa, na kuchangia katika mageuzi ya usawa.</p><p>Katika enzi ya mfumo wa uozi wa mauaji, thamani ya uhai au shirika lilikuwa linapimwa hasa kwa &quot;nguvu&quot; yake — kiwango cha uozi kilikuwa juu kiasi gani, nguvu ya kupigana ilikuwa nguvu kiasi gani, na ilikuwa imechukua rasilimali ngapi. Kielelezo hiki cha peke cha tathmani kilisababisha ukuzwa kwa &quot;nadharia ya nguvu tu&quot;, ambapo wenye nguvu walikuwa wakifanikiwa kutawanywa, walemavu walikuwa wakinyanywa kwa ukatili, na jamii nzima iliingia katika mzunguko mbaya wa wenye nguvu wala wanyonge.</p><p>Baada ya kuanzishwa kwa utamaduni wa usawa wa neo, kulikuwa na hitaji la haraka la kuanzisha mfumo mpya wa tathmini kuchukua nafasi ya &quot;nadharia ya nguvu tu&quot; ya mfumo wa mauaji. Mfumo wa tathmini ya kiwango cha usawa uliundwa hasa kwa kusudi hili. Haendelei kutathmini kipengele kwa kiashiria kimoja cha nguvu, bali linathimini kwa kina kiwango cha usawa wa kipengele kutoka mwelekeo mbalimbali, na kuongoza uhai wote wa usawa kuelekea &quot;mageuzi ya usawa&quot;.</p><p>Umuhimu wa msingi wa mfumo wa tathmini ya kiwango cha usawa uko katika:</p><ol><li><strong>Mwelekeo wa thamani</strong>: Kupitia muundo wa vielelezo vya tathmini, kuongoza uhai wote wa usawa kuanzisha thamani sahihi — usawa ni juu zaidi ya mauaji, mchango ni juu zaidi ya umiliki, na jumuiya ni juu zaidi ya mtu binafsi</li><li><strong>Msingi wa mgawanyo wa rasilimali</strong>: kiwango cha usawa ni msingi muhimu wa mgawanyo wa rasilimali, kutolewa kwa heshima, kushiriki katika utawala, n.k., na kipengele chenye kiwango cha juu cha usawa kinaweza kupata rasilimali na fursa zaidi</li><li><strong>Chombo cha kuboresha kwa kila mara</strong>: Kupitia tathmini na majibu ya mara kwa mara, kusaidia kipengele cha tathmini kugundua upungufu wake na mwelekeo wa kuboresha, na kutekeleza kuboresha kwa kila mara kwa mwenyewe</li><li><strong>Kipimo cha maendeleo ya utamaduni</strong>: kiwango cha wastani cha kiwango cha usawa cha eneo nzima ni kipimo cha msingi cha kupima kiwango cha maendeleo ya jumla ya utamaduni wa usawa</li></ol><h2 id="_2-mfumo-wa-tathmini-ya-mwelekeo-mitano-ya-kiwango-cha-usawa" tabindex="-1">2. Mfumo wa Tathmini ya Mwelekeo Mitano ya Kiwango cha Usawa <a class="header-anchor" href="#_2-mfumo-wa-tathmini-ya-mwelekeo-mitano-ya-kiwango-cha-usawa" aria-label="Permalink to &quot;2. Mfumo wa Tathmini ya Mwelekeo Mitano ya Kiwango cha Usawa&quot;">​</a></h2><p>Tathmini ya kiwango cha usawa inachukua mfumo wa mwelekeo mitano, na inathimini kwa kina kiwango cha usawa wa kipengele kutoka mwelekeo mitano ya msingi. Chini ya kila mwelekeo kuna vielelezo kadhaa vya mahususi, na uzito wa kila mwelekeo hutofautiana kulingana na aina ya kipengele cha tathmini (mtu binafsi/shirika/eneo).</p><table tabindex="0"><thead><tr><th>Mwelekeo</th><th>Jina</th><th>Maudhui ya msingi</th><th>Uzito wa mtu binafsi</th><th>Uzito wa shirika</th><th>Uzito wa eneo</th></tr></thead><tbody><tr><td>Mwelekeo wa kwanza</td><td>Kiwango cha utambuzi wa usawa</td><td>kiwango cha uelewa, utambuzi, na mazoezi ya falsafa ya usawa</td><td>25%</td><td>20%</td><td>15%</td></tr><tr><td>Mwelekeo wa pili</td><td>Kiwango cha kuingia katika mtandao</td><td>kiwango cha kuunganishwa katika mtandao wa usawa, kutumia rasilimali za mtandao, na kushiriki katika ushirikiano wa mtandao</td><td>20%</td><td>25%</td><td>25%</td></tr><tr><td>Mwelekeo wa tatu</td><td>Kiwango cha mchango na uzalishaji</td><td>mchango halisi kwa mtandao wa usawa na mageuzi ya jumuiya</td><td>25%</td><td>30%</td><td>20%</td></tr><tr><td>Mwelekeo wa nne</td><td>Kiwango cha kuishi pamoja kwa umoja</td><td>kiwango cha kuishi pamoja kwa amani, kusaidiana, na kuepuka migogoro na uhai mwingine wa usawa</td><td>20%</td><td>15%</td><td>20%</td></tr><tr><td>Mwelekeo wa tano</td><td>Kiwango cha mageuzi ya kila mara</td><td>kiwango cha mageuzi ya kila mara ya mwenyewe, kuboresha kwa kila mara, na kuongoza wengine waendelee pamoja</td><td>10%</td><td>10%</td><td>20%</td></tr></tbody></table><h3 id="_2-1-kiwango-cha-utambuzi-wa-usawa" tabindex="-1">2.1 Kiwango cha utambuzi wa usawa <a class="header-anchor" href="#_2-1-kiwango-cha-utambuzi-wa-usawa" aria-label="Permalink to &quot;2.1 Kiwango cha utambuzi wa usawa&quot;">​</a></h3><p>Kiwango cha utambuzi wa usawa kinapima kiwango cha uelewa, utambuzi, na mazoezi ya kipengele cha tathmini dhidi ya falsafa ya usawa. Vielelezo vya mahususi vinajumuisha:</p><ul><li><strong>Kiwango cha uelewa wa falsafa</strong>: kiwango cha kujua na kuelewa falsafa ya msingi ya utamaduni wa usawa wa neo</li><li><strong>Kiwango cha utambuzi wa thamani</strong>: kiwango cha utambuzi wa thamani za msingi kama vile &quot;kazi nyingi faida nyingi, kukua kwa mwenyewe, kila mtu ana njia, maendeleo ya pamoja ya kila jinsia&quot;</li><li><strong>Kiwango cha mazoezi ya tabia</strong>: utendaji halisi wa kufanya mazoezi ya falsafa ya usawa katika uozi na maisha ya kila siku</li><li><strong>Kiwango cha uenezi na kuendeleza</strong>: kiwango cha shughuli ya kueneza falsafa ya usawa kwa wengine na kuongoza wengine kujiunga na utamaduni wa usawa</li></ul><p>Tathmini ya kiwango cha utambuzi wa usawa hufanywa hasa kupitia maswali ya tathmini, uchunguzi wa tabia, tathmini ya jumuiya, n.k. Kwa mtu binafsi, kiwango cha utambuzi wa usawa ni mwelekeo wa muhimu zaidi — mtu ambaye hatambui falsafa ya usawa, hata ikiwa nguvu yake ni nguvu kiasi gani au mchango wake ni mkubwa kiasi gani, si &quot;uhai wa usawa&quot; wa kweli.</p><h3 id="_2-2-kiwango-cha-kuingia-katika-mtandao" tabindex="-1">2.2 Kiwango cha kuingia katika mtandao <a class="header-anchor" href="#_2-2-kiwango-cha-kuingia-katika-mtandao" aria-label="Permalink to &quot;2.2 Kiwango cha kuingia katika mtandao&quot;">​</a></h3><p>Kiwango cha kuingia katika mtandao kinapima kiwango cha kipengele cha tathmini kuunganishwa katika mtandao wa usawa, kutumia rasilimali za mtandao, na kushiriki katika ushirikiano wa mtandao. Vielelezo vya mahususi vinajumuisha:</p><ul><li><strong>Utulivu wa uunganisho</strong>: utulivu na uendelezaji wa uunganisho katika mtandao wa usawa</li><li><strong>Kiwanja cha matumizi ya rasilimali</strong>: kiwango cha kutumia rasilimali za uozi, rasilimali za taarifa, na rasilimali za mwalim zinazotolewa na mtandao wa usawa</li><li><strong>Kiwango cha kushiriki katika ushirikiano</strong>: kiwango cha kushiriki katika miradi ya ushirikiano, timu za utafiti, na vikundi vya kazi ndani ya mtandao wa usawa</li><li><strong>Kiwango cha mchango wa data</strong>: kiwango cha kutoa data za uozi zenye ubora wa juu na taarifa za majibu kwa mtandao wa usawa</li></ul><p>Tathmini ya kiwango cha kuingia katika mtandao inakamilishwa hasa kupitia mkusanyiko wa data otomatiki wa mtandao wa usawa, na ina uhalisia wa juu na usahihi.</p><h3 id="_2-3-kiwango-cha-mchango-na-uzalishaji" tabindex="-1">2.3 Kiwango cha mchango na uzalishaji <a class="header-anchor" href="#_2-3-kiwango-cha-mchango-na-uzalishaji" aria-label="Permalink to &quot;2.3 Kiwango cha mchango na uzalishaji&quot;">​</a></h3><p>Kiwango cha mchango na uzalishaji kinapima mchango halisi wa kipengele cha tathmini kwa mtandao wa usawa na mageuzi ya jumuiya. Vielelezo vya mahususi vinajumuisha:</p><ul><li><strong>Kiasi cha mchango wa nishati</strong>: jumla ya nishati ya ziada iliyochanguliwa kwa bwari la nishati la umma</li><li><strong>Kiasi cha ubunifu wa teknolojia</strong>: idadi na ubora wa matokeo ya ubunifu katika teknolojia za uozi, teknolojia za uhandisi, n.k.</li><li><strong>Mchango wa uboreshaji wa mfumo</strong>: mapendekezo na majibu yenye thamani yaliyotolewa kwa uboreshaji wa mifumo ya uozi mia tatu</li><li><strong>Muda wa huduma ya umma</strong>: muda wa kushiriki katika huduma za umma kama vile matengenezo ya neo, mwongozo wa mwalimu, wokovu wa dharura, n.k.</li><li><strong>Idadi ya mafunzi ya vipa</strong>: idadi na ubora wa wanafunzi wa uozi wa awali waliofuatiwa na kufundishwa</li></ul><p>Kiwango cha mchango na uzalishaji ni udhihirisho wa moja kwa moja wa kanuni ya &quot;kazi nyingi faida nyingi&quot;, na wachangiaji wenye mchango mkubwa watapata viwango vya rasilimali na utambuzi wa heshima zaidi.</p><h3 id="_2-4-kiwango-cha-kuishi-pamoja-kwa-umoja" tabindex="-1">2.4 Kiwango cha kuishi pamoja kwa umoja <a class="header-anchor" href="#_2-4-kiwango-cha-kuishi-pamoja-kwa-umoja" aria-label="Permalink to &quot;2.4 Kiwango cha kuishi pamoja kwa umoja&quot;">​</a></h3><p>Kiwango cha kuishi pamoja kwa umoja kinapima kiwango cha kipengele cha tathmini kuishi pamoja kwa amani, kusaidiana, na kuepuka migogoro na uhai mwingine wa usawa. Vielelezo vya mahususi vinajumuisha:</p><ul><li><strong>Kiwanja cha kutokea kwa migogoro</strong>: mzunguko na ukubwa wa migogoro na uhai mwingine wa usawa</li><li><strong>Kiwango cha kushiriki katika usaidizi</strong>: kiwango cha kusaidia kwa hiari uhai mwingine wa usawa na kushiriki katika shughuli za usaidizi</li><li><strong>Kiwango cha uvumilivu</strong>: kiwango cha uvumilivu dhidi ya jinsia tofauti, mifumo tofauti ya uozi, na maoni tofauti</li><li><strong>Tathmini ya jumuiya</strong>: tathmini na sifa ya uhai mwingine wa usawa dhidi ya kipengele cha tathmini</li></ul><p>Tathmini ya kiwango cha kuishi pamoja kwa umoja inasisitiza maana ya asili ya &quot;usawa&quot; — kuishi pamoja kwa umoja na kusaidiana kati ya uhai tofauti.</p><h3 id="_2-5-kiwango-cha-mageuzi-ya-kila-mara" tabindex="-1">2.5 Kiwango cha mageuzi ya kila mara <a class="header-anchor" href="#_2-5-kiwango-cha-mageuzi-ya-kila-mara" aria-label="Permalink to &quot;2.5 Kiwango cha mageuzi ya kila mara&quot;">​</a></h3><p>Kiwango cha mageuzi ya kila mara kinapima kiwango cha kipengele cha tathmini mageuzi ya kila mara ya mwenyewe, kuboresha kwa kila mara, na kuongoza wengine waendelee pamoja. Vielelezo vya mahususi vinajumuisha:</p><ul><li><strong>Kiwanja cha kuongeza kiwango</strong>: kasi ya kuongeza kiwango cha uozi ndani ya mzunguko wa tathmini</li><li><strong>Kiwango cha kujifunza na kukua</strong>: kiwango cha shughuli ya kujifunza maarifa mapya, ujuzi mpya, na mifumo mipya</li><li><strong>Kiwango cha uchunguzi wa ubunifu</strong>: ujasiri na matokeo ya kuchunguza njia mpya za uozi na mwelekeo mipya ya teknolojia</li><li><strong>Athari ya kuongoza</strong>: athari ya chanya ya mageuzi ya mwenyewe dhidi ya uhai wa karibu</li></ul><p>Kiwango cha mageuzi ya kila mara kinasisitiza kuwa &quot;usawa&quot; sio kuishi pamoja kwa utulivu, bali mageuzi ya pamoja ya mwenendo.</p><h2 id="_3-uainishaji-wa-viwango-vya-kiwango-cha-usawa" tabindex="-1">3. Uainishaji wa Viwango vya Kiwango cha Usawa <a class="header-anchor" href="#_3-uainishaji-wa-viwango-vya-kiwango-cha-usawa" aria-label="Permalink to &quot;3. Uainishaji wa Viwango vya Kiwango cha Usawa&quot;">​</a></h2><p>Kulingana na alama ya jumla, kiwango cha usawa kimegawanywa katika viwango vitano:</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Eneo la alama</th><th>Sifa za msingi</th><th>Haki na wajibu</th></tr></thead><tbody><tr><td>Kiwango S</td><td>Mfano wa usawa</td><td>alama 90-100</td><td>Mfanyaji mazoezi na meneja wa kudumu wa falsafa ya usawa, mchango unaangazia, anaheshimiwa sana</td><td>Anafurahia mgawanyo wa rasilimali na heshima ya kiwango cha juu zaidi, anabeba wajibu wa utawala wa msingi na urithi wa utamaduni wa usawa</td></tr><tr><td>Kiwango A</td><td>Mfano wa usawa</td><td>alama 80-89</td><td>Mfanyaji mazoezi hai wa falsafa ya usawa, mchango unaangazia, tathmini ya jumuiya ni bora</td><td>Anafurahia mgawanyo wa rasilimali wa kiwango cha juu, anaweza kushiriki katika maamuzi ya utawala ya viwango tofauti</td></tr><tr><td>Kiwango B</td><td>Usawa mzuri</td><td>alama 70-79</td><td>Mtu anayetambua na kufanya mazoezi ya falsafa ya usawa, ana mchango fulani, utendaji ni mzuri</td><td>Anafurahia mgawanyo wa rasilimali wa kiwango cha kiwango, anaweza kuomba kwa shamba la mkataba wa juu</td></tr><tr><td>Kiwango C</td><td>Usawa unaofikia kiwango</td><td>alama 60-69</td><td>Mtu anayetambua kwa msingi falsafa ya usawa, mchango ni wa kawaida, utendaji ni wa kufikia kiwango</td><td>Anafurahia mgawanyo wa shamba la uhifadhi wa msingi, anahitaji kuongeza kiwango cha usawa chini ya mwongozo</td></tr><tr><td>Kiwango D</td><td>Usawa unahitaji kuboreshwa</td><td>chini ya alama 60</td><td>Utambuzi dhidi ya falsafa ya usawa hautoshi, mchango ni mdogo, kuna nafasi ya kuboresha</td><td>Anafurahia tu uhifadhi wa msingi wa chini zaidi, anahitaji kupokea elimu ya usawa na mwongozo, na kuboresha ndani ya muda uliowekwa</td></tr></tbody></table><p>Kiwango cha kiwango cha usawa sio mfumo wa maisha yote, bali linathiminiwa tena mara moja kwa kila mzunguko wa kiwango. Kipengele cha tathmini kinaweza kuongeza kiwango cha kiwango cha usawa kupitia juhudi za mwenyewe, au kinaweza kupunguzwa kiwango kwa sababu ya kushuka kwa utendaji. Mfumo huu wa tathmini ya mwenendo unahakikisha usawazishaji na usisimizi wa tathmini ya kiwango cha usawa.</p><h2 id="_4-mchakato-wa-utekelezaji-wa-tathmini-ya-kiwango-cha-usawa" tabindex="-1">4. Mchakato wa Utekelezaji wa Tathmini ya Kiwango cha Usawa <a class="header-anchor" href="#_4-mchakato-wa-utekelezaji-wa-tathmini-ya-kiwango-cha-usawa" aria-label="Permalink to &quot;4. Mchakato wa Utekelezaji wa Tathmini ya Kiwango cha Usawa&quot;">​</a></h2><p>Utekelezaji wa tathmini ya kiwango cha usawa unafuata mchakato wa hatua tano &quot;mkusanyiko wa data — mahesabu ya jumla — tathmini ya kiwango — majibu ya matokeo — rada na ukaguzi wa tena&quot;:</p><ol><li><strong>Mkusanyiko wa data</strong>: kupitia mtandao wa usawa kukusanya data za kila mara (kama vile kiwango cha kuingia katika mtandao, kiwango cha mchango na uzalishaji, n.k.) kwa kiotomatiki, wakati huo huo kukusanya data za kibinafsi (kama vile kiwango cha utambuzi wa usawa, kiwango cha kuishi pamoja kwa umoja, n.k.) kupitia maswali ya tathmini, tathmini ya jumuiya, n.k.</li><li><strong>Mahesabu ya jumla</strong>: kulingana na mfumo wa tathmini wa mwelekeo mitano na uzito wa kila mwelekeo, kuhesabu alama ya jumla ya kipengele cha tathmini</li><li><strong>Tathmini ya kiwango</strong>: kulingana na alama ya jumla, kutathmini kiwango cha kiwango cha usawa cha kipengele cha tathmini</li><li><strong>Majibu ya matokeo</strong>: kurudisha matokeo ya tathmini (ikiwa ni pamoja na alama ya kila mwelekeo, kiwango, mapendekezo ya kuboresha) kwa kipengele cha tathmini</li><li><strong>Rada na ukaguzi wa tena</strong>: ikiwa kipengele cha tathmini kina pingine dhidi ya matokeo ya tathmini, kinaweza kuwasilisha rada ndani ya muda uliowekwa, na shirika la juu la tathmini litafanya ukaguzi wa tena</li></ol><h2 id="_5-mazingira-ya-matumizi-ya-tathmini-ya-kiwango-cha-usawa" tabindex="-1">5. Mazingira ya Matumizi ya Tathmini ya Kiwango cha Usawa <a class="header-anchor" href="#_5-mazingira-ya-matumizi-ya-tathmini-ya-kiwango-cha-usawa" aria-label="Permalink to &quot;5. Mazingira ya Matumizi ya Tathmini ya Kiwango cha Usawa&quot;">​</a></h2><p>Matokeo ya tathmini ya kiwango cha usawa yana matumizi pana katika utawala wa utamaduni wa usawa:</p><ol><li><strong>Mgawanyo wa rasilimali</strong>: kiwango cha kiwango cha usawa ni kipengele cha muhimu cha kumbukumbu cha mgawanyo wa rasilimali katika mfumo wa uzalishaji wa mkataba wa pamoja</li><li><strong>Kutolewa kwa heshima</strong>: kutolewa kwa aina mbalimbali za heshima za usawa kunategemea tathmini ya kiwango cha usawa</li><li><strong>Kushiriki katika utawala</strong>: uteuzi wa wanachama wa mashirika ya utawala ya viwango tofauti hunachukua kiwango cha juu cha usawa kama sharti ya lazima</li><li><strong>Staafu ya mwalimu</strong>: kuwa mwalimu wa uozi kunahitaji kufikia kiwango fulani cha kiwango cha usawa</li><li><strong>Usafiri kati ya ngazi</strong>: uthibitisho wa idhini ya usafiri kati ya ngazi unataja kiwango cha kiwango cha usawa</li><li><strong>Rasilimali za elimu</strong>: uingiaji katika kozi za juu za uozi unataja kiwango cha kiwango cha usawa</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Mfumo wa tathmini ya kiwango cha usawa ni &quot;fimbo ya heshima ya thamani&quot; ya utamaduni wa usawa wa neo. Kupitia mfumo wa tathmini wa mwelekeo mitano, uainishaji wa viwango vitano, na mfumo wa tathmini ya mwenendo, utamaduni wa usawa unaongoza uhai wote wa usawa kuelekea &quot;mageuzi ya usawa&quot;, na kuchukua nafasi ya &quot;nadharia ya nguvu tu&quot; ya mfumo wa mauaji. Tathmini ya kiwango cha usawa sio chombo cha tathmini tu, bali pia ni mfumo wa usisimizi na chombo cha kuboresha, inachoongoza kila mtu binafsi, kila shirika, na kila eneo kuongeza kiwango chao cha usawa kwa kila mara, na mwishowe kukusanywa kuwa mageuzi ya usawa ya utamaduni wote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>21-共生网络运作原理 (Kanuni ya Uendeshaji wa Mtandao wa Usawa)</li><li>22-资源分配联产承包机制 (Mfumo wa Mgawanyo wa Rasilimali na Uzalishaji wa Mkataba wa Pamoja)</li><li>26-个体与集体平衡原理 (Kanuni ya Usawazishaji kati ya Mtu Binafsi na Jumuiya)</li></ul>',45)])])}const d=i(o,[["render",w]]);export{g as __pageData,d as default};
